// MySpace\MyS_Front\src\paginas\perfil\EditarPerfil.jsx

import React, { useState } from 'react';
import './EditarPerfil.css';

import menuItems from '../../data/menuItems';
import postsData from '../../data/postData';
import perfilData from '../../data/perfilData';

// importe de las bases
import Base_Main from "../../bases/Base_Main";
import Base_AsideIZ from "../../bases/Base_AsideIZ";
import Base_AsideDE from "../../bases/Base_AsideDE";
import { useNavigate } from 'react-router';

// Helper para obtener usuario de forma segura
const getUsuarioLogeado = () => {
  try {
    const data = localStorage.getItem("usuarioLogeado");
    return data ? JSON.parse(data) : null;
  } catch (error) {
    console.error("Error al leer usuario:", error);
    return null;
  }
};

const EditarPerfil = () => {

    // --- Datos principales ---
    const usuarioLogeado = getUsuarioLogeado();
    //const [comentarioVisibleId, setComentarioVisibleId] = useState(null);
    const [activeTab, setActiveTab] = useState('comentarios'); // 'comentarios', 'publicaciones', 'todo'
    const navigate = useNavigate

    // --- Lógica de renderizado de contenido dinámico ---
    const renderizarContenidoPosts = () => {
        // En una aplicación real, aquí filtrarías los postsData 
        // para mostrar solo comentarios o solo publicaciones.
        // Como 'postsData' es la fuente de datos, asumiremos que todos 
        // son posts por ahora y simplemente los listaremos.
        // Si tu 'postsData' contuviera un campo 'tipo: "comentario" | "publicacion"',
        // el filtro se aplicaría aquí:
        let postsAmostrar = postsData;

